.draft-table-scroll { overflow-x:auto; max-width:100%; border:1px solid var(--border); border-radius:8px; }
.draft-table { border-collapse:collapse; width:100%; min-width:670px; text-align:left; font-size:13px; }
.draft-table th { color:var(--text-light); background:var(--bg); font-size:12px; white-space:nowrap; }
.draft-table th, .draft-table td { padding:14px 12px; border-bottom:1px solid var(--border); vertical-align:middle; }
.draft-table tr:last-child td { border-bottom:0; }
.draft-table td:first-child { min-width:170px; overflow-wrap:anywhere; }
.draft-table td span { display:block; color:var(--text-light); margin-top:4px; font-size:12px; }
.draft-table td:nth-child(2) { font-variant-numeric:tabular-nums; }
.draft-table td:last-child .btn { white-space:nowrap; }
#myDraftsOverlay .modal-hdr, #publishedProjectActionsOverlay .modal-hdr { gap:16px; align-items:center; }
