#myDraftsOverlay .modal-x, #publishedProjectActionsOverlay .modal-x { flex:0 0 36px; height:36px; }
.published-project-actions-body { display:grid; gap:12px; }
#publishedProjectActionsMessage { margin:0 0 8px; font-size:14px; line-height:1.6; overflow-wrap:anywhere; }
.project-lifecycle-actions { display:flex; flex-wrap:wrap; gap:10px; margin-top:8px; }
.project-lifecycle-actions .btn { white-space:normal; height:auto; min-height:42px; }
.project-more-actions { flex:0 0 32px; width:32px; height:32px; font-size:22px; }
@media (max-width:600px) {
  #myDraftsOverlay .modal, #publishedProjectActionsOverlay .modal { width:calc(100vw - 24px) !important; padding:18px; }
